class Session(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    id: Annotated[str, Field(pattern='^[0-9A-HJKMNP-TV-Z]{26}$')]
    person: Annotated[
        str,
        Field(
            description="A person's unique, permanent name: shown as @handle, and the name of their people/<handle>/ directory.",
            pattern='^[a-z0-9](?:[a-z0-9-]{0,30}[a-z0-9])?$',
        ),
    ]
    harness: Literal['composer', 'codex', 'claude']
    office: str
    cwd: str
    repo_commit: Annotated[
        str, Field(description='A git commit or blob id.', pattern='^[0-9a-f]{40,64}$')
    ]
    status: Literal['starting', 'idle', 'busy', 'waiting', 'ending', 'debriefing', 'ended', 'failed', 'interrupted']
    kind: Literal['main', 'side', 'profile_manager']
    waiting_on: Annotated[
        list[Handle],
        Field(
            description='While status is waiting: who must act (answer an open question, or raise the cost cap), in the order those opened. Empty otherwise.'
        ),
    ] = []
    capped: Annotated[
        bool,
        Field(
            description="True while the session's cost is at or over its cost cap: its turns wait until someone raises the cap, and its status is waiting."
        ),
    ] = False
    harness_session_id: str | None = None
    work_item_id: Ulid | None = None
    run_ids: list[str] = []
    question_id: Ulid | None = None
    seed: str | None = None
    cost: Annotated[float, Field(ge=0.0)] = 0
    cost_cap_usd: Annotated[
        CostCapUsd | None,
        Field(description='null means company.defaults.cost_cap_usd.'),
    ] = None
    opened_by: Annotated[
        Handle | None,
        Field(
            description='The human who opened the session; null for sessions from before this field or opened by the office itself.'
        ),
    ] = None
    connection: Annotated[
        ConnectionName | None,
        Field(
            description="The chat's connection on its office. Null: `office`, for sessions from before this field; every new session sets it."
        ),
    ] = None
    model: Annotated[
        str | None,
        Field(
            description="Null: the connection's own model. For Azure, a deployment name."
        ),
    ] = None
    model_note: Annotated[
        str | None,
        Field(
            description="Why the chat isn't on the model it was asked to start on, or why it moved."
        ),
    ] = None
    harness_model: Annotated[
        str | None,
        Field(
            description="The model the harness runs, as it reports it (a Codex session: Codex's load response); null until the harness reports it, and for composer sessions."
        ),
    ] = None
    harness_usage: Annotated[
        HarnessUsage | None,
        Field(
            description="This session's own token counts so far, as the harness reports them. A continued session counts only its own stretch: add its parent chain's counts for the thread's total. Null until the harness reports any; always null for composer sessions."
        ),
    ] = None
    parent_session_id: Annotated[
        Ulid | None,
        Field(
            description='The session this one directly continues, on the same harness thread; follow its parent_session_id for earlier stretches. Null for a first stretch.'
        ),
    ] = None
    created_at: Annotated[
        str,
        Field(
            description='UTC, ISO-8601 in milliseconds with a Z suffix. Fixed width, so string order is time order; a plain string, so it round-trips unchanged.',
            pattern='^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\\.[0-9]{3}Z$',
        ),
    ]
    updated_at: Annotated[
        str,
        Field(
            description='UTC, ISO-8601 in milliseconds with a Z suffix. Fixed width, so string order is time order; a plain string, so it round-trips unchanged.',
            pattern='^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\\.[0-9]{3}Z$',
        ),
    ]


type SetupPrompt = Annotated[
    SetupAsk | SetupChoose | SetupSecret | SetupSay | SetupStep,
    Field(
        description="One line `python -m opencorp.install init|onboard --json-prompts` writes on stdout: a question for `opencorp`'s setup screen, or something to show.",
        discriminator='type',
    ),
]


class Message(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    id: Annotated[str, Field(pattern='^[0-9A-HJKMNP-TV-Z]{26}$')]
    session_id: Annotated[str, Field(pattern='^[0-9A-HJKMNP-TV-Z]{26}$')]
    role: Literal['user', 'assistant']
    author: Annotated[
        Handle | None,
        Field(
            description='The human who sent a user message. A harness session names every sender; null for assistant messages, for composer sessions, and for rows from before this field.'
        ),
    ] = None
    parts: list[
        Annotated[
            TextPart | FilePart | ToolPart | ErrorPart, Field(discriminator='type')
        ]
    ]
    created_at: Annotated[
        str,
        Field(
            description='UTC, ISO-8601 in milliseconds with a Z suffix. Fixed width, so string order is time order; a plain string, so it round-trips unchanged.',
            pattern='^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\\.[0-9]{3}Z$',
        ),
    ]


AnswerField.model_rebuild()
RunSummary.model_rebuild()
